export interface ProbedImage {
  mime: "image/png" | "image/jpeg" | "image/gif" | "image/webp";
  width: number;
  height: number;
}

export interface SanitizedImageBytes {
  image: ProbedImage;
  bytes: Buffer;
  trailingBytes: number;
}

type SupportedImageMime = ProbedImage["mime"];

const PNG_SIGNATURE = Buffer.from("89504e470d0a1a0a", "hex");
const JPEG_SOF_MARKERS = new Set([
  0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf,
]);

function invalid(mime: string, detail: string): never {
  throw new Error(`invalid ${mime} image structure: ${detail}`);
}

function ascii(buffer: Buffer, start: number, length: number): string {
  return buffer.toString("ascii", start, start + length);
}

function detectMime(buffer: Buffer): SupportedImageMime | null {
  if (buffer.length >= 8 && buffer.subarray(0, 8).equals(PNG_SIGNATURE)) return "image/png";
  if (buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
    return "image/jpeg";
  }
  if (
    buffer.length >= 6 &&
    (ascii(buffer, 0, 6) === "GIF87a" || ascii(buffer, 0, 6) === "GIF89a")
  ) {
    return "image/gif";
  }
  if (buffer.length >= 12 && ascii(buffer, 0, 4) === "RIFF" && ascii(buffer, 8, 4) === "WEBP") {
    return "image/webp";
  }
  return null;
}

function crc32(buffer: Buffer, start: number, end: number): number {
  let crc = 0xffffffff;
  for (let index = start; index < end; index += 1) {
    crc ^= buffer[index]!;
    for (let bit = 0; bit < 8; bit += 1) {
      crc = (crc >>> 1) ^ (crc & 1 ? 0xedb88320 : 0);
    }
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function probePng(buffer: Buffer): ProbedImage {
  if (buffer.length < 33) invalid("PNG", "truncated header");
  let offset = 8;
  let width = 0;
  let height = 0;
  let chunks = 0;
  let sawData = false;
  while (offset < buffer.length) {
    if (offset + 12 > buffer.length) invalid("PNG", "truncated chunk header");
    const length = buffer.readUInt32BE(offset);
    const typeStart = offset + 4;
    const dataStart = typeStart + 4;
    const dataEnd = dataStart + length;
    const chunkEnd = dataEnd + 4;
    if (chunkEnd > buffer.length) invalid("PNG", "truncated chunk payload");
    const type = ascii(buffer, typeStart, 4);
    if (!/^[A-Za-z]{4}$/.test(type)) invalid("PNG", "invalid chunk type");
    if (buffer.readUInt32BE(dataEnd) !== crc32(buffer, typeStart, dataEnd)) {
      invalid("PNG", `${type} CRC mismatch`);
    }
    if (chunks === 0) {
      if (type !== "IHDR" || length !== 13) invalid("PNG", "IHDR must be first");
      width = buffer.readUInt32BE(dataStart);
      height = buffer.readUInt32BE(dataStart + 4);
      if (width === 0 || height === 0) invalid("PNG", "zero dimensions");
      if (buffer[dataStart + 10] !== 0 || buffer[dataStart + 11] !== 0) {
        invalid("PNG", "unsupported compression or filter method");
      }
      if ((buffer[dataStart + 12] ?? 2) > 1) invalid("PNG", "invalid interlace method");
    }
    if (type === "IDAT") sawData = true;
    if (type === "IEND") {
      if (length !== 0 || !sawData || chunkEnd !== buffer.length) {
        invalid("PNG", "invalid IEND or missing image data");
      }
      return { mime: "image/png", width, height };
    }
    offset = chunkEnd;
    chunks += 1;
  }
  return invalid("PNG", "missing IEND");
}

interface ProbedJpeg {
  image: ProbedImage;
  consumedBytes: number;
}

function probeJpeg(buffer: Buffer, allowTrailingBytes = false): ProbedJpeg {
  if (buffer.length < 16) invalid("JPEG", "truncated header");
  let offset = 2;
  let width = 0;
  let height = 0;
  let sawScan = false;
  let sawQuantization = false;
  let sawEntropyTable = false;

  while (offset < buffer.length) {
    if (buffer[offset] !== 0xff) invalid("JPEG", "expected marker");
    while (buffer[offset] === 0xff) offset += 1;
    if (offset >= buffer.length) invalid("JPEG", "truncated marker");
    const marker = buffer[offset++]!;
    if (marker === 0xd9) {
      if (!width || !height || !sawScan || !sawQuantization || !sawEntropyTable) {
        invalid("JPEG", "missing frame, tables, or scan");
      }
      if (offset !== buffer.length && !allowTrailingBytes) {
        invalid("JPEG", "trailing bytes after EOI");
      }
      return {
        image: { mime: "image/jpeg", width, height },
        consumedBytes: offset,
      };
    }
    if (marker === 0x00 || marker === 0xd8) invalid("JPEG", "invalid marker ordering");
    if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) continue;
    if (offset + 2 > buffer.length) invalid("JPEG", "truncated segment length");
    const segmentLength = buffer.readUInt16BE(offset);
    if (segmentLength < 2 || offset + segmentLength > buffer.length) {
      invalid("JPEG", "truncated segment");
    }
    const payload = offset + 2;
    const segmentEnd = offset + segmentLength;
    if (JPEG_SOF_MARKERS.has(marker)) {
      if (segmentLength < 8) invalid("JPEG", "short SOF segment");
      height = buffer.readUInt16BE(payload + 1);
      width = buffer.readUInt16BE(payload + 3);
      if (!width || !height) invalid("JPEG", "zero dimensions");
    } else if (marker === 0xdb) {
      sawQuantization = true;
    } else if (marker === 0xc4 || marker === 0xcc) {
      sawEntropyTable = true;
    } else if (marker === 0xda) {
      if (segmentLength < 6) invalid("JPEG", "short SOS segment");
      sawScan = true;
      offset = segmentEnd;
      while (offset < buffer.length) {
        if (buffer[offset] !== 0xff) {
          offset += 1;
          continue;
        }
        let next = offset + 1;
        while (buffer[next] === 0xff) next += 1;
        if (next >= buffer.length) invalid("JPEG", "truncated entropy marker");
        const code = buffer[next]!;
        if (code === 0x00 || (code >= 0xd0 && code <= 0xd7)) {
          offset = next + 1;
          continue;
        }
        // Let the outer marker parser consume EOI or a progressive scan marker.
        break;
      }
      continue;
    }
    offset = segmentEnd;
  }
  return invalid("JPEG", "missing EOI");
}

function validateImageInput(
  declaredMime: string,
  bytes: Uint8Array,
): { buffer: Buffer; detected: SupportedImageMime } {
  const buffer = Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const mime = declaredMime === "image/jpg" ? "image/jpeg" : declaredMime;
  const detected = detectMime(buffer);
  if (!detected) throw new Error("image byte signature is not a supported image");
  if (detected !== mime) {
    throw new Error(`image MIME ${mime} does not match byte signature ${detected}`);
  }
  return { buffer, detected };
}

function skipGifSubBlocks(buffer: Buffer, start: number): number {
  let offset = start;
  while (offset < buffer.length) {
    const length = buffer[offset++]!;
    if (length === 0) return offset;
    if (offset + length > buffer.length) invalid("GIF", "truncated data sub-block");
    offset += length;
  }
  return invalid("GIF", "unterminated data sub-blocks");
}

function probeGif(buffer: Buffer): ProbedImage {
  if (buffer.length < 14) invalid("GIF", "truncated logical screen descriptor");
  const width = buffer.readUInt16LE(6);
  const height = buffer.readUInt16LE(8);
  if (!width || !height) invalid("GIF", "zero dimensions");
  const globalTableBytes = buffer[10]! & 0x80 ? 3 * 2 ** ((buffer[10]! & 0x07) + 1) : 0;
  let offset = 13 + globalTableBytes;
  if (offset > buffer.length) invalid("GIF", "truncated global color table");
  let sawImage = false;
  while (offset < buffer.length) {
    const introducer = buffer[offset]!;
    if (introducer === 0x3b) {
      if (!sawImage || offset + 1 !== buffer.length) invalid("GIF", "invalid trailer");
      return { mime: "image/gif", width, height };
    }
    if (introducer === 0x21) {
      if (offset + 2 > buffer.length) invalid("GIF", "truncated extension");
      offset = skipGifSubBlocks(buffer, offset + 2);
      continue;
    }
    if (introducer !== 0x2c || offset + 10 > buffer.length) {
      invalid("GIF", "invalid image block");
    }
    const packed = buffer[offset + 9]!;
    offset += 10;
    if (packed & 0x80) offset += 3 * 2 ** ((packed & 0x07) + 1);
    if (offset >= buffer.length) invalid("GIF", "truncated local table or LZW header");
    const minimumCodeSize = buffer[offset++]!;
    if (minimumCodeSize < 2 || minimumCodeSize > 11) invalid("GIF", "invalid LZW code size");
    offset = skipGifSubBlocks(buffer, offset);
    sawImage = true;
  }
  return invalid("GIF", "missing trailer");
}

function readUint24LE(buffer: Buffer, offset: number): number {
  return buffer[offset]! | (buffer[offset + 1]! << 8) | (buffer[offset + 2]! << 16);
}

function probeWebp(buffer: Buffer): ProbedImage {
  if (buffer.length < 20) invalid("WebP", "truncated RIFF header");
  if (buffer.readUInt32LE(4) !== buffer.length - 8) invalid("WebP", "RIFF size mismatch");
  let offset = 12;
  let width = 0;
  let height = 0;
  let sawImagePayload = false;
  while (offset < buffer.length) {
    if (offset + 8 > buffer.length) invalid("WebP", "truncated chunk header");
    const type = ascii(buffer, offset, 4);
    const size = buffer.readUInt32LE(offset + 4);
    const payload = offset + 8;
    const end = payload + size;
    const paddedEnd = end + (size & 1);
    if (end > buffer.length || paddedEnd > buffer.length) invalid("WebP", "truncated chunk");
    if (type === "VP8 ") {
      if (
        size < 10 ||
        buffer[payload + 3] !== 0x9d ||
        buffer[payload + 4] !== 0x01 ||
        buffer[payload + 5] !== 0x2a
      ) {
        invalid("WebP", "invalid VP8 frame header");
      }
      width = buffer.readUInt16LE(payload + 6) & 0x3fff;
      height = buffer.readUInt16LE(payload + 8) & 0x3fff;
      sawImagePayload = true;
    } else if (type === "VP8L") {
      if (size < 5 || buffer[payload] !== 0x2f) invalid("WebP", "invalid VP8L header");
      const bits = buffer.readUInt32LE(payload + 1);
      if (bits >>> 29) invalid("WebP", "unsupported VP8L version");
      width = (bits & 0x3fff) + 1;
      height = ((bits >>> 14) & 0x3fff) + 1;
      sawImagePayload = true;
    } else if (type === "VP8X") {
      if (size !== 10) invalid("WebP", "invalid VP8X header");
      width = readUint24LE(buffer, payload + 4) + 1;
      height = readUint24LE(buffer, payload + 7) + 1;
    } else if (type === "ANMF") {
      if (size < 16) invalid("WebP", "short animation frame");
      sawImagePayload = true;
    }
    offset = paddedEnd;
  }
  if (offset !== buffer.length || !width || !height || !sawImagePayload) {
    invalid("WebP", "missing dimensions or image payload");
  }
  return { mime: "image/webp", width, height };
}

/** Strictly verify byte signature, bounded container structure, and declared MIME. */
export function probeImageBytes(declaredMime: string, bytes: Uint8Array): ProbedImage {
  const { buffer, detected } = validateImageInput(declaredMime, bytes);
  switch (detected) {
    case "image/png":
      return probePng(buffer);
    case "image/jpeg":
      return probeJpeg(buffer).image;
    case "image/gif":
      return probeGif(buffer);
    case "image/webp":
      return probeWebp(buffer);
  }
}

/**
 * Verify untrusted image bytes and remove data after a complete JPEG EOI marker.
 * Other image formats remain strict, and the returned JPEG is probed again after truncation.
 */
export function sanitizeImageBytes(declaredMime: string, bytes: Uint8Array): SanitizedImageBytes {
  const { buffer, detected } = validateImageInput(declaredMime, bytes);
  if (detected !== "image/jpeg") {
    return { image: probeImageBytes(declaredMime, buffer), bytes: buffer, trailingBytes: 0 };
  }

  const probed = probeJpeg(buffer, true);
  const trailingBytes = buffer.length - probed.consumedBytes;
  if (trailingBytes === 0) {
    return { image: probed.image, bytes: buffer, trailingBytes };
  }

  const sanitized = buffer.subarray(0, probed.consumedBytes);
  return {
    image: probeImageBytes("image/jpeg", sanitized),
    bytes: sanitized,
    trailingBytes,
  };
}

export type InputAttachmentKind = "image" | "file" | "directory";

export type InputAttachmentOrigin =
  | "paste"
  | "os-drop"
  | "file-panel"
  | "picker"
  | "mention"
  | "generated"
  | "mobile"
  | "im-gateway"
  | "tool";

export interface InputAttachmentMeta {
  id: string;
  sessionId: string;
  kind: InputAttachmentKind;
  origin: InputAttachmentOrigin;
  path: string;
  absPath: string;
  relPath?: string;
  mime?: string;
  size: number;
  sha256: string;
  originalName?: string;
  createdAt: number;
  sourcePath?: string;
  width?: number;
  height?: number;
  vision?: {
    include: boolean;
    mediaPath?: string;
    detail?: "low" | "standard" | "high";
  };
  directory?: {
    treePath?: string;
    truncated?: boolean;
    entryCount?: number;
  };
}

export interface StageImageDataUrlInput {
  cwd: string;
  sessionId: string;
  name?: string;
  mime?: string;
  dataUrl: string;
  origin: InputAttachmentOrigin;
}

export interface StageImageBytesInput {
  cwd: string;
  sessionId: string;
  name?: string;
  mime: string;
  bytes?: Uint8Array;
  sourceFile?: string;
  origin: InputAttachmentOrigin;
}

export interface StageFileBytesInput {
  cwd: string;
  sessionId: string;
  name?: string;
  mime?: string;
  bytes: Uint8Array;
  origin: InputAttachmentOrigin;
}

export interface AttachmentCleanupInput {
  cwd: string;
  sessionId?: string;
  now?: number;
}

export interface AttachmentInspectInput {
  cwd: string;
  sessionId?: string;
}

interface ManifestRecord {
  event: "staged" | "sent" | "removedFromDraft" | "cleanup";
  id?: string;
  sessionId: string;
  kind?: InputAttachmentKind;
  origin?: InputAttachmentOrigin;
  path?: string;
  absPath?: string;
  relPath?: string;
  mime?: string;
  size?: number;
  sha256?: string;
  originalName?: string;
  createdAt?: number;
  sentAt?: number;
  removedAt?: number;
  cleanedAt?: number;
  status?: "draft" | "sent";
}

const CODE_SHELL_DIR = ".code-shell";
const ATTACHMENTS_DIR = "attachments";
const MANIFEST_FILE = "manifest.jsonl";
const GITIGNORE_CONTENT = "*\n!.gitignore\n";
export const DRAFT_ATTACHMENT_TTL_MS = 24 * 60 * 60 * 1000;
export const SENT_ATTACHMENT_TTL_MS = 30 * 24 * 60 * 60 * 1000;
export const MAX_STAGED_IMAGE_BYTES = 10 * 1024 * 1024;
export const MAX_STAGED_FILE_BYTES = 20 * 1024 * 1024;
const MAX_ATTACHMENT_NAME_CHARS = 1_024;
const MAX_ATTACHMENT_MIME_CHARS = 256;
const MAX_MANIFEST_LINE_BYTES = 128 * 1024;
const MAX_MANIFEST_SCAN_BYTES = 32 * 1024 * 1024;
const MAX_MANIFEST_RECORDS = 50_000;
const MAX_ATTACHMENT_SESSION_DIRS = 10_000;

const ATTACHMENT_ORIGINS = new Set<InputAttachmentOrigin>([
  "paste",
  "os-drop",
  "file-panel",
  "picker",
  "mention",
  "generated",
  "mobile",
  "im-gateway",
  "tool",
]);

function assertAttachmentLabels(input: {
  name?: string;
  mime?: string;
  origin: InputAttachmentOrigin;
}): void {
  if (
    (input.name !== undefined &&
      (typeof input.name !== "string" ||
        input.name.length > MAX_ATTACHMENT_NAME_CHARS ||
        input.name.includes("\0"))) ||
    (input.mime !== undefined &&
      (typeof input.mime !== "string" ||
        input.mime.length > MAX_ATTACHMENT_MIME_CHARS ||
        input.mime.includes("\0"))) ||
    !ATTACHMENT_ORIGINS.has(input.origin)
  ) {
    throw new Error("invalid attachment metadata");
  }
}

const IMAGE_MIME_EXT: Record<string, string> = {
  "image/png": ".png",
  "image/jpeg": ".jpg",
  "image/jpg": ".jpg",
  "image/webp": ".webp",
  "image/gif": ".gif",
};

const ALLOWED_IMAGE_MIMES = new Set(Object.keys(IMAGE_MIME_EXT));

let idCounter = 0;

export async function stageImageDataUrl(
  input: StageImageDataUrlInput,
): Promise<InputAttachmentMeta> {
  const parsed = parseDataUrl(input.dataUrl);
  if (!parsed || !ALLOWED_IMAGE_MIMES.has(parsed.mime)) {
    throw new Error(`unsupported image data URL MIME`);
  }
  if (input.mime && normalizeMime(input.mime) !== parsed.mime) {
    throw new Error(`data URL MIME ${parsed.mime} does not match declared MIME ${input.mime}`);
  }
  return stageImageBuffer(input, parsed.mime, parsed.buffer);
}

/** Stage already-transferred bytes without expanding them back through base64. */
export async function stageImageBytes(input: StageImageBytesInput): Promise<InputAttachmentMeta> {
  assertAttachmentLabels(input);
  const mime = normalizeMime(input.mime);
  if (!ALLOWED_IMAGE_MIMES.has(mime)) throw new Error(`unsupported image MIME ${input.mime}`);
  if ((input.bytes === undefined) === (input.sourceFile === undefined)) {
    throw new Error("exactly one of bytes or sourceFile is required");
  }
  let buffer: Buffer;
  if (input.sourceFile !== undefined) {
    if (
      typeof input.sourceFile !== "string" ||
      !input.sourceFile ||
      input.sourceFile.length > 32_768 ||
      input.sourceFile.includes("\0")
    ) {
      throw new Error("image source path is invalid");
    }
    const handle = await open(
      input.sourceFile,
      fsConstants.O_RDONLY | (fsConstants.O_NOFOLLOW ?? 0),
    );
    try {
      const source = await handle.stat();
      if (!source.isFile()) throw new Error("image source must be a regular file");
      if (source.size > MAX_STAGED_IMAGE_BYTES) {
        throw new Error(
          `image attachment exceeds size limit (${formatBytes(MAX_STAGED_IMAGE_BYTES)})`,
        );
      }
      buffer = await handle.readFile();
    } finally {
      await handle.close();
    }
  } else {
    buffer = Buffer.from(input.bytes!);
  }
  return stageImageBuffer(input, mime, buffer);
}

async function stageImageBuffer(
  input: {
    cwd: string;
    sessionId: string;
    name?: string;
    origin: InputAttachmentOrigin;
  },
  mime: string,
  buffer: Buffer,
): Promise<InputAttachmentMeta> {
  assertAttachmentLabels(input);
  const cwd = await resolveExistingDirectory(input.cwd, "cwd");
  assertSafeSessionId(input.sessionId);
  if (buffer.byteLength > MAX_STAGED_IMAGE_BYTES) {
    throw new Error(`image attachment exceeds size limit (${formatBytes(MAX_STAGED_IMAGE_BYTES)})`);
  }
  const sanitized = sanitizeImageBytes(mime, buffer);
  buffer = sanitized.bytes;
  const image = sanitized.image;

  const attachmentsRoot = await ensureAttachmentsRoot(cwd);
  const sessionDir = await ensureSessionDir(attachmentsRoot, input.sessionId);
  const sha256 = createHash("sha256").update(buffer).digest("hex");
  const sha16 = sha256.slice(0, 16);
  const ext = IMAGE_MIME_EXT[mime] ?? ".bin";
  const safeBase = safeSlug(input.name, "image");
  const existing = await findExistingSessionFile(sessionDir, sha16);
  const filename = existing ?? `${sha16}-${safeBase}${ext}`;
  const absPath = await safeJoin(sessionDir, filename, sessionDir);

  if (!existing) {
    const tmpPath = await safeJoin(
      sessionDir,
      `.${filename}.${process.pid}.${Date.now()}.tmp`,
      sessionDir,
    );
    await writeFile(tmpPath, buffer, { flag: "wx" });
    try {
      await rename(tmpPath, absPath);
    } catch (error) {
      await rm(tmpPath, { force: true }).catch(() => undefined);
      throw error;
    }
  }

  const relPath = normalizePath(relative(cwd, absPath));
  const createdAt = Date.now();
  idCounter += 1;
  const meta: InputAttachmentMeta = {
    id: `att_${sha16}_${idCounter.toString(36)}`,
    sessionId: input.sessionId,
    kind: "image",
    origin: input.origin,
    path: relPath,
    absPath,
    relPath,
    mime,
    size: buffer.byteLength,
    sha256,
    ...(input.name ? { originalName: input.name } : {}),
    createdAt,
    width: image.width,
    height: image.height,
    vision: { include: true },
  };
  await appendManifest(sessionDir, { event: "staged", status: "draft", ...meta });
  return meta;
}

/** Stage an untrusted non-image file inside the canonical attachment root. */
export async function stageFileBytes(input: StageFileBytesInput): Promise<InputAttachmentMeta> {
  assertAttachmentLabels(input);
  const cwd = await resolveExistingDirectory(input.cwd, "cwd");
  assertSafeSessionId(input.sessionId);
  const buffer = Buffer.from(input.bytes);
  if (buffer.byteLength > MAX_STAGED_FILE_BYTES) {
    throw new Error(`file attachment exceeds size limit (${formatBytes(MAX_STAGED_FILE_BYTES)})`);
  }

  const attachmentsRoot = await ensureAttachmentsRoot(cwd);
  const sessionDir = await ensureSessionDir(attachmentsRoot, input.sessionId);
  const sha256 = createHash("sha256").update(buffer).digest("hex");
  const sha16 = sha256.slice(0, 16);
  const safeBase = safeSlug(input.name, "file");
  const rawExt = extname(basename(input.name ?? ""));
  const originalExt = /^\.[A-Za-z0-9]{1,15}$/.test(rawExt) ? rawExt : "";
  const existing = await findExistingSessionFile(sessionDir, sha16);
  const filename = existing ?? `${sha16}-${safeBase}${originalExt}`;
  const absPath = await safeJoin(sessionDir, filename, sessionDir);

  if (!existing) {
    const tmpPath = await safeJoin(
      sessionDir,
      `.${filename}.${process.pid}.${Date.now()}.tmp`,
      sessionDir,
    );
    await writeFile(tmpPath, buffer, { flag: "wx" });
    try {
      await rename(tmpPath, absPath);
    } catch (error) {
      await rm(tmpPath, { force: true }).catch(() => undefined);
      throw error;
    }
  }

  const relPath = normalizePath(relative(cwd, absPath));
  const createdAt = Date.now();
  idCounter += 1;
  const meta: InputAttachmentMeta = {
    id: `att_${sha16}_${idCounter.toString(36)}`,
    sessionId: input.sessionId,
    kind: "file",
    origin: input.origin,
    path: relPath,
    absPath,
    relPath,
    mime: normalizeMime(input.mime) || "application/octet-stream",
    size: buffer.byteLength,
    sha256,
    ...(input.name ? { originalName: basename(input.name) } : {}),
    createdAt,
  };
  await appendManifest(sessionDir, { event: "staged", status: "draft", ...meta });
  return meta;
}

export async function markAttachmentsSent(
  cwd: string,
  sessionId: string,
  attachments: InputAttachmentMeta[],
): Promise<void> {
  if (attachments.length === 0) return;
  const resolvedCwd = await resolveExistingDirectory(cwd, "cwd");
  assertSafeSessionId(sessionId);
  const sessionDir = await ensureSessionDir(await ensureAttachmentsRoot(resolvedCwd), sessionId);
  const sentAt = Date.now();
  for (const attachment of attachments) {
    if (attachment.sessionId !== sessionId) continue;
    await appendManifest(sessionDir, {
      event: "sent",
      id: attachment.id,
      sessionId,
      kind: attachment.kind,
      origin: attachment.origin,
      path: attachment.path,
      absPath: attachment.absPath,
      relPath: attachment.relPath,
      mime: attachment.mime,
      size: attachment.size,
      sha256: attachment.sha256,
      originalName: attachment.originalName,
      sentAt,
      status: "sent",
    });
  }
}

export async function listRecentAttachments(
  input: AttachmentInspectInput,
): Promise<InputAttachmentMeta[]> {
  const cwd = await resolveExistingDirectory(input.cwd, "cwd");
  const root = await resolveAttachmentsRoot(cwd);
  if (!root) return [];
  const sessionIds = input.sessionId ? [input.sessionId] : await listSafeSessionDirs(root);
  const staged = new Map<string, InputAttachmentMeta>();
  const sent = new Set<string>();
  for (const sessionId of sessionIds) {
    assertSafeSessionId(sessionId);
    const sessionDir = await safeJoin(root, sessionId, root).catch(() => null);
    if (!sessionDir) continue;
    const records = await readManifest(sessionDir);
    for (const record of records) {
      if (record.event === "staged") {
        const meta = recordToMeta(record);
        if (meta && (await pathExistsInside(meta.absPath, root))) {
          staged.set(meta.id, meta);
        }
      } else if (record.event === "sent" && record.id) {
        sent.add(record.id);
      } else if ((record.event === "removedFromDraft" || record.event === "cleanup") && record.id) {
        staged.delete(record.id);
      }
    }
  }
  return [...staged.values()]
    .filter((meta) => sent.has(meta.id) || meta.kind !== "image")
    .sort((a, b) => b.createdAt - a.createdAt)
    .slice(0, 50);
}

export async function cleanupAttachments(input: AttachmentCleanupInput): Promise<{
  removed: string[];
  sessionsRemoved: string[];
}> {
  const cwd = await resolveExistingDirectory(input.cwd, "cwd");
  const root = await resolveAttachmentsRoot(cwd);
  if (!root) return { removed: [], sessionsRemoved: [] };
  const now = input.now ?? Date.now();
  const sessionIds = input.sessionId ? [input.sessionId] : await listSafeSessionDirs(root);
  const removed: string[] = [];
  const sessionsRemoved: string[] = [];

  for (const sessionId of sessionIds) {
    assertSafeSessionId(sessionId);
    const sessionDir = await safeJoin(root, sessionId, root).catch(() => null);
    if (!sessionDir) continue;
    const records = await readManifest(sessionDir);
    if (input.sessionId) {
      const files = await manifestFilesInside(records, root);
      for (const file of files) {
        await rm(file, { force: true }).catch(() => undefined);
        removed.push(file);
      }
      await rm(sessionDir, { recursive: true, force: true }).catch(() => undefined);
      sessionsRemoved.push(sessionId);
      continue;
    }

    const latest = latestAttachmentState(records);
    for (const state of latest.values()) {
      const createdAt = state.createdAt ?? 0;
      const sentAt = state.sentAt;
      const isSent = typeof sentAt === "number";
      const ttl = isSent ? SENT_ATTACHMENT_TTL_MS : DRAFT_ATTACHMENT_TTL_MS;
      const basis = isSent ? sentAt : createdAt;
      if (!basis || now - basis < ttl) continue;
      if (!state.absPath || !(await pathExistsInside(state.absPath, root))) continue;
      await rm(state.absPath, { force: true }).catch(() => undefined);
      removed.push(state.absPath);
      await appendManifest(sessionDir, {
        event: "cleanup",
        id: state.id,
        sessionId,
        absPath: state.absPath,
        relPath: state.relPath,
        path: state.path,
        sha256: state.sha256,
        cleanedAt: now,
      });
    }
  }

  return { removed, sessionsRemoved };
}

function normalizeMime(mime: string | undefined): string {
  return String(mime ?? "")
    .trim()
    .toLowerCase();
}

function parseDataUrl(dataUrl: string): { mime: string; buffer: Buffer } | null {
  if (typeof dataUrl !== "string") return null;
  const match = /^data:([^;,]+);base64,([\s\S]*)$/.exec(dataUrl);
  if (!match) return null;
  const mime = normalizeMime(match[1]);
  const base64 = (match[2] ?? "").replace(/\s+/g, "");
  const decodedSize = byteLengthFromBase64(base64);
  if (decodedSize > MAX_STAGED_IMAGE_BYTES) {
    throw new Error(
      `image attachment exceeds decoded size limit (${formatBytes(MAX_STAGED_IMAGE_BYTES)})`,
    );
  }
  try {
    const buffer = Buffer.from(base64, "base64");
    if (buffer.byteLength > MAX_STAGED_IMAGE_BYTES) {
      throw new Error(
        `image attachment exceeds decoded size limit (${formatBytes(MAX_STAGED_IMAGE_BYTES)})`,
      );
    }
    return { mime, buffer };
  } catch (error) {
    if (String((error as Error).message).includes("decoded size limit")) throw error;
    return null;
  }
}

function byteLengthFromBase64(base64: string): number {
  if (!base64) return 0;
  const padding = base64.endsWith("==") ? 2 : base64.endsWith("=") ? 1 : 0;
  return Math.max(0, Math.floor((base64.length * 3) / 4) - padding);
}

function safeSlug(name: string | undefined, fallback: string): string {
  const base = basename(String(name ?? fallback));
  const noExt = base.slice(0, base.length - extname(base).length) || fallback;
  const slug = noExt
    .normalize("NFKC")
    .replace(/[\u0000-\u001f\u007f<>:"/\\|?*]+/g, "-")
    .replace(/\s+/g, "-")
    .replace(/^\.+|\.+$/g, "")
    .replace(/-+/g, "-")
    .slice(0, 80)
    .replace(/[-. ]+$/g, "");
  return slug || fallback;
}

async function findExistingSessionFile(sessionDir: string, sha16: string): Promise<string | null> {
  let entries: string[];
  try {
    entries = await readdir(sessionDir);
  } catch {
    return null;
  }
  for (const entry of entries) {
    if (!entry.startsWith(`${sha16}-`) || entry === MANIFEST_FILE) continue;
    const info = await lstat(join(sessionDir, entry));
    if (info.isSymbolicLink() || !info.isFile()) {
      throw new Error("existing attachment hash entry must be a regular file, not a symlink");
    }
    return entry;
  }
  return null;
}

async function appendManifest(sessionDir: string, record: ManifestRecord): Promise<void> {
  const manifest = await safeJoin(sessionDir, MANIFEST_FILE, sessionDir);
  const serialized = JSON.stringify(record);
  if (Buffer.byteLength(serialized, "utf8") > MAX_MANIFEST_LINE_BYTES) {
    throw new Error("attachment manifest record exceeds the size limit");
  }
  await appendFile(manifest, `${serialized}\n`, { encoding: "utf-8", mode: 0o600 });
}

async function readManifest(sessionDir: string): Promise<ManifestRecord[]> {
  try {
    const manifest = await safeJoin(sessionDir, MANIFEST_FILE, sessionDir);
    const handle = await open(manifest, "r");
    let raw: string;
    try {
      const stat = await handle.stat();
      if (!stat.isFile()) return [];
      const length = Math.min(stat.size, MAX_MANIFEST_SCAN_BYTES);
      const start = stat.size - length;
      const buffer = Buffer.allocUnsafe(length);
      let total = 0;
      while (total < length) {
        const { bytesRead } = await handle.read(buffer, total, length - total, start + total);
        if (bytesRead === 0) break;
        total += bytesRead;
      }
      let window = buffer.subarray(0, total);
      if (start > 0) {
        const newline = window.indexOf(0x0a);
        if (newline < 0) return [];
        window = window.subarray(newline + 1);
      }
      raw = window.toString("utf8");
    } finally {
      await handle.close();
    }
    return raw
      .split("\n")
      .filter((line) => line.length > 0 && Buffer.byteLength(line, "utf8") <= MAX_MANIFEST_LINE_BYTES)
      .map((line) => {
        try {
          return parseManifestRecord(JSON.parse(line) as unknown);
        } catch {
          return null;
        }
      })
      .filter((record): record is ManifestRecord => !!record)
      .slice(-MAX_MANIFEST_RECORDS);
  } catch {
    return [];
  }
}

function parseManifestRecord(value: unknown): ManifestRecord | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const raw = value as Record<string, unknown>;
  if (
    (raw.event !== "staged" &&
      raw.event !== "sent" &&
      raw.event !== "removedFromDraft" &&
      raw.event !== "cleanup") ||
    typeof raw.sessionId !== "string"
  ) {
    return null;
  }
  try {
    assertSafeSessionId(raw.sessionId);
  } catch {
    return null;
  }
  for (const field of [
    "id",
    "path",
    "absPath",
    "relPath",
    "mime",
    "sha256",
    "originalName",
  ] as const) {
    const item = raw[field];
    if (item !== undefined && (typeof item !== "string" || item.length > 32_768 || item.includes("\0"))) {
      return null;
    }
  }
  if (
    raw.kind !== undefined &&
    raw.kind !== "image" &&
    raw.kind !== "file" &&
    raw.kind !== "directory"
  ) {
    return null;
  }
  if (raw.origin !== undefined && !ATTACHMENT_ORIGINS.has(raw.origin as InputAttachmentOrigin)) {
    return null;
  }
  for (const field of ["size", "createdAt", "sentAt", "removedAt", "cleanedAt"] as const) {
    const item = raw[field];
    if (item !== undefined && (typeof item !== "number" || !Number.isFinite(item))) return null;
  }
  return raw as unknown as ManifestRecord;
}

function recordToMeta(record: ManifestRecord): InputAttachmentMeta | null {
  if (
    !record.id ||
    !record.sessionId ||
    !record.kind ||
    !record.origin ||
    !record.path ||
    !record.absPath ||
    typeof record.size !== "number" ||
    !record.sha256 ||
    typeof record.createdAt !== "number"
  ) {
    return null;
  }
  return {
    id: record.id,
    sessionId: record.sessionId,
    kind: record.kind,
    origin: record.origin,
    path: record.path,
    absPath: record.absPath,
    relPath: record.relPath,
    mime: record.mime,
    size: record.size,
    sha256: record.sha256,
    originalName: record.originalName,
    createdAt: record.createdAt,
    vision: record.kind === "image" ? { include: true } : undefined,
  };
}

function latestAttachmentState(records: ManifestRecord[]): Map<string, ManifestRecord> {
  const latest = new Map<string, ManifestRecord>();
  for (const record of records) {
    if (!record.id) continue;
    if (record.event === "staged") latest.set(record.id, record);
    if (record.event === "sent") {
      const prev = latest.get(record.id) ?? record;
      latest.set(record.id, { ...prev, ...record, status: "sent" });
    }
    if (record.event === "removedFromDraft" || record.event === "cleanup") latest.delete(record.id);
  }
  return latest;
}

